const start = new Date(String(row.starts_at)).getTime();
const end = new Date(String(row.ends_at)).getTime();
if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) return "A time slot ends after it starts.";
if (end - start > 24 * 3600 * 1000) return "A time slot is at most 24 hours long.";
const cap = Number(row.capacity);
return (Number.isInteger(cap) && cap >= 1 && cap <= 500) || "Capacity is a whole number from 1 to 500.";

const rows = (r: unknown): Array<Record<string, unknown>> => (Array.isArray(r) ? r : (r as { rows?: Array<Record<string, unknown>> }).rows ?? []);
const hit = rows(await ctx.db.query("select id from slot where resource_id = $1 and id::text <> coalesce($2::text, '') and status <> 'closed' and starts_at < $3 and ends_at > $4 limit 1", [row.resource_id, row.id ?? null, row.ends_at, row.starts_at]));
return hit.length === 0 || "That overlaps another time for the same {{param.attach_to|title}}. Pick a different time.";

if (!row.organisation_id) return true;
const r = await ctx.db.query('select "{{param.org_field}}" as org from "{{param.attach_to}}" where id = $1', [row.resource_id]);
const rows = Array.isArray(r) ? r : (r as { rows?: Array<Record<string, unknown>> }).rows ?? [];
return String(rows[0]?.org ?? "") === String(row.organisation_id) || "A time slot belongs to the organisation of what is booked.";

const rows = (r: unknown): Array<Record<string, unknown>> => (Array.isArray(r) ? r : (r as { rows?: Array<Record<string, unknown>> }).rows ?? []);
const s = rows(await ctx.db.query("select capacity, booked, starts_at, ends_at, status from slot where id = $1", [row.slot_id]))[0];
if (!s) return "That time is no longer available.";
if (String(s.status) === "closed") return "That time is closed for booking.";
if (new Date(String(s.starts_at)).getTime() <= ctx.now().getTime()) return "That time has already started.";
const seats = Number(row.seats ?? 1);
if (!Number.isInteger(seats) || seats < 1 || seats > 20) return "Book between 1 and 20 places.";
const left = Number(s.capacity ?? 0) - Number(s.booked ?? 0);
return seats <= left || (left <= 0 ? "That time is full. Try another one." : `Only ${left} ${left === 1 ? "place is" : "places are"} left.`);

const rows = (r: unknown): Array<Record<string, unknown>> => (Array.isArray(r) ? r : (r as { rows?: Array<Record<string, unknown>> }).rows ?? []);
const s = rows(await ctx.db.query("select starts_at, ends_at from slot where id = $1", [row.slot_id]))[0];
if (!s) return true;
const who = row.booker_id ?? (await ctx.me("{{param.booker_role}}"));
if (!who) return true;
const clash = rows(await ctx.db.query("select r.id from reservation r join slot s on s.id = r.slot_id where r.booker_id = $1 and r.status <> 'cancelled' and s.starts_at < $2 and s.ends_at > $3 limit 1", [who, s.ends_at, s.starts_at]));
return clash.length === 0 || "You already have a booking at that time.";

const rows = (r: unknown): Array<Record<string, unknown>> => (Array.isArray(r) ? r : (r as { rows?: Array<Record<string, unknown>> }).rows ?? []);
if (!ctx.old || !ctx.user || ctx.user.role !== "{{param.booker_role}}") return true;
for (const f of ["slot_id", "booker_id", "seats", "status", "note"]) {
  if (String(ctx.old[f] ?? "") !== String(row[f] ?? "")) return "You can cancel a booking, not change it.";
}
if (String(row.cancel_request ?? "none") !== "requested") return "You can cancel a booking, not change it.";
const s = rows(await ctx.db.query("select starts_at from slot where id = $1", [row.slot_id]))[0];
return !s || new Date(String(s.starts_at)).getTime() > ctx.now().getTime() || "That time has already started.";

do.code:
const s = await ctx.db.get("slot", String(row["slot_id"] ?? ""));
if (!s) return;
await ctx.db.update("slot", String(s["id"]), { booked: Number(s["booked"] ?? 0) + Number(row["seats"] ?? 1) });

const s = await ctx.db.get("slot", String(row["slot_id"] ?? ""));
if (!s) return;
await ctx.db.update("slot", String(s["id"]), { booked: Math.max(0, Number(s["booked"] ?? 0) - Number(row["seats"] ?? 1)) });

if (row["organisation_id"]) return;
const resource = await ctx.db.get("{{param.attach_to}}", String(row["resource_id"] ?? ""));
const org = resource ? resource["{{param.org_field}}"] : null;
if (org) await ctx.db.update("slot", String(row["id"]), { organisation_id: String(org) });
